import React, { useEffect, useState } from 'react'
import { supabase } from '../lib/supabase'
import { formatCLP } from '../lib/calculos'

export default function Ventas() {
  const [recetas, setRecetas] = useState([])
  const [form, setForm] = useState({ fecha: new Date().toISOString().split('T')[0], receta_nombre: '', litros: 1, precio_venta: '', delivery: '', nota: '' })
  const [ventas, setVentas] = useState([])
  const [toast, setToast] = useState('')
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    async function load() {
      const [{ data: r }, { data: v }] = await Promise.all([
        supabase.from('recetas').select('nombre').order('nombre'),
        supabase.from('ventas').select('*').order('fecha', { ascending: false }).limit(20)
      ])
      setRecetas((r || []).filter(x => x.nombre !== 'ENVASE'))
      setVentas(v || [])
    }
    load()
  }, [])

  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(''), 2500) }

  const getPrecioSugerido = (nombre) => {
    const n = nombre.toLowerCase()
    if (n.includes('colada')) return 9000
    if (n.includes('daikiri')) return 8000
    return 9000
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!form.receta_nombre || !form.precio_venta) return
    setLoading(true)
    const { error } = await supabase.from('ventas').insert({
      fecha: form.fecha,
      receta_nombre: form.receta_nombre,
      litros: parseFloat(form.litros),
      precio_venta: parseFloat(form.precio_venta),
      delivery: parseFloat(form.delivery) || 0,
      nota: form.nota || null
    })
    if (!error) {
      showToast('Venta registrada ✓')
      setForm(f => ({ ...f, receta_nombre: '', litros: 1, precio_venta: '', delivery: '', nota: '' }))
      const { data: v } = await supabase.from('ventas').select('*').order('fecha', { ascending: false }).limit(20)
      setVentas(v || [])
    }
    setLoading(false)
  }

  return (
    <div className="page">
      {toast && <div className="toast">{toast}</div>}
      <div className="page-title">Registrar venta</div>
      <form onSubmit={handleSubmit}>
        <div className="card">
          <div className="form-group">
            <label className="form-label">Fecha</label>
            <input type="date" className="form-input" value={form.fecha}
              onChange={e => setForm(f => ({ ...f, fecha: e.target.value }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Receta</label>
            <select className="form-select" value={form.receta_nombre}
              onChange={e => {
                const r = e.target.value
                setForm(f => ({ ...f, receta_nombre: r, precio_venta: r ? getPrecioSugerido(r) : '' }))
              }}>
              <option value="">Seleccionar receta...</option>
              {recetas.map(r => <option key={r.nombre} value={r.nombre}>{r.nombre}</option>)}
            </select>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div className="form-group">
              <label className="form-label">Litros</label>
              <input type="number" step="0.5" min="0.5" className="form-input" value={form.litros}
                onChange={e => setForm(f => ({ ...f, litros: e.target.value }))} />
            </div>
            <div className="form-group">
              <label className="form-label">Precio/L ($)</label>
              <input type="number" className="form-input" value={form.precio_venta}
                onChange={e => setForm(f => ({ ...f, precio_venta: e.target.value }))} />
            </div>
          </div>
          {form.precio_venta && form.litros && (
            <div style={{ color: '#00ff88', fontSize: 15, marginBottom: 12, textAlign: 'center', fontWeight: 700 }}>
              Total: {formatCLP(parseFloat(form.litros) * parseFloat(form.precio_venta))}
            </div>
          )}
          <div className="form-group">
            <label className="form-label">Delivery cobrado ($) — opcional</label>
            <input type="number" className="form-input" value={form.delivery} placeholder="0"
              onChange={e => setForm(f => ({ ...f, delivery: e.target.value }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Nota — opcional</label>
            <input type="text" className="form-input" value={form.nota}
              placeholder="ej: descuento 10%, devolución envase..."
              onChange={e => setForm(f => ({ ...f, nota: e.target.value }))} />
          </div>
          <button type="submit" className="btn btn-primary" disabled={loading}>
            {loading ? 'Guardando...' : 'Registrar venta'}
          </button>
        </div>
      </form>
      <div className="section-divider">Historial reciente</div>
      <div className="card">
        {ventas.length === 0 && <div style={{ color: 'var(--muted)', textAlign: 'center', padding: 20 }}>Sin ventas aún</div>}
        {ventas.map(v => (
          <div className="list-item" key={v.id}>
            <div>
              <div className="list-item-name">{v.receta_nombre}</div>
              <div className="list-item-sub">{v.fecha} · {v.litros}L</div>
              {v.nota && <div className="list-item-sub" style={{ color: 'var(--purple)' }}>{v.nota}</div>}
            </div>
            <div className="list-item-right">
              <div className="list-item-value">{formatCLP(v.litros * v.precio_venta)}</div>
              {v.delivery > 0 && <div className="list-item-muted">+{formatCLP(v.delivery)} delivery</div>}
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}
